const CN_DOMAINS = /\.(cn|com\.cn|net\.cn|org\.cn)$|(baidu|zhihu|weibo|xiaohongshu|douyin|bilibili|douban|36kr|huxiu|thepaper|people|xinhua|cctv|sspai|v2ex|juejin|csdn|aliyun|tencentcloud|zcool|huaban|lanhu|mastergo|jsdesign|gaoding|iconfont|58pic|tuchong|jiyan|kling|doubao|kimi|wenxin|metaso|nanoai|feishu|yuque|shimo|mubu|dida|tencentdoc|wps|pkulaw|wenshu|tianyancha|qcc|lawtime|chinacourt|cnipa|moj|flk|rmfy|juliang|newrank|chanmama|feigua|baiduindex|wechatindex|iresearch|questmobile|adquan|socialbeta|woshipm|pmcaff|modao|eastmoney|ths|chinamoney|sse|szse|yonyou|kingdee|stats|zhipin|maimai|liepin|lagou|51job|zhaopin|shixiseng|smartedu|zxxk|jyeoo|jiaoan|seewo|icourse163|xuetangx|nowcoder|shanshan|dxy|drugs|medlive|haodf|medscape|cma|nhc|jianying|creator_douyin|creator_xhs|creator_bili|mp|feigua|fanruan|tableau|powerbi|baidu_tj|ga|zhiyun|termonline|tac|alibaba|made-in-china|globalsources|aliexpress|singlewindow|customs|dhl|shopify|dianxiaomi|iqiyi|tencentvideo|youku|xigua|meituan|ag_|ctrip|12306|woshipm|woshipm|xiaohongshu)/i;

function detectCn(domain) {
  if (CN_DOMAINS.test(domain)) return true;
  // 常见国际站在国内也能直连的
  const accessible = ['unsplash', 'pexels', 'github', 'stackoverflow', 'mdn', 'npmjs', 'figma', 'notion', 'trello', 'wikipedia', 'deepl', 'grammarly', 'civitai', 'midjourney', 'runway', 'pika', 'suno', 'chatgpt', 'claude'];
  return accessible.some((d) => domain.includes(d));
}

